362	// isOutdated compares current and latest versions using semantic versioning.
363	// Returns true if current < latest.
364	func isOutdated(current, latest string) bool {
365		// Ensure versions have "v" prefix for semver package
366		if !strings.HasPrefix(current, "v") {
367			current = "v" + current
368		}
369		if !strings.HasPrefix(latest, "v") {
370			latest = "v" + latest
371		}
372	
373		// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
374		// These are local development builds and shouldn't trigger update notifications.
375		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
376		if strings.Contains(semver.Prerelease(current), "dev") {
377			return false
378		}
379	
380		// semver.Compare returns -1 if current < latest
381		return semver.Compare(current, latest) < 0
382	}
