    30	// CheckAndNotify performs a version check and notifies the user if a newer version is available.
    31	// This is the main entry point for the version check system.
    32	// The function is silent on all errors to avoid interrupting CLI operations.
    33	func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
    34		// Skip checks for dev builds
    35		if currentVersion == "dev" || currentVersion == "" {
    36			return
    37		}
    38	
    39		// Ensure the global config directory exists
    40		if err := ensureGlobalConfigDir(); err != nil {
    41			// Silent failure - don't block CLI operations
    42			return
    43		}
    44	
    45		// Load the cache to check when we last fetched
    46		cache, err := loadCache()
    47		if err != nil {
    48			cache = &VersionCache{}
    49		}
    50	
    51		// Skip if we checked recently (within 24 hours)
    52		if time.Since(cache.LastCheckTime) < checkInterval {
    53			return
    54		}
    55	
    56		// Fetch the latest version from the appropriate channel
    57		var latestVersion string
    58		if isNightly(currentVersion) {
    59			latestVersion, err = fetchLatestNightlyVersion(ctx)
    60		} else {
    61			latestVersion, err = fetchLatestVersion(ctx)
    62		}
    63	
    64		// Always update cache to avoid retrying on every CLI invocation
    65		cache.LastCheckTime = time.Now()
    66		if saveErr := saveCache(cache); saveErr != nil {
    67			logging.Debug(ctx, "version check: failed to save cache",
    68				"error", saveErr.Error())
    69		}
    70	
    71		if err != nil {
    72			logging.Debug(ctx, "version check: failed to fetch latest version",
    73				"error", err.Error())
    74			return
    75		}
    76	
    77		// Show notification if outdated
    78		if isOutdated(currentVersion, latestVersion) {
    79			printNotification(w, currentVersion, latestVersion)
    80		}
    81	}
