   375		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
   376		if strings.Contains(semver.Prerelease(current), "dev") {
   377			return false
   378		}
   379	
   380		// semver.Compare returns -1 if current < latest
   381		return semver.Compare(current, latest) < 0
   382	}
